import { createClient, type SupabaseClient } from 'npm:@supabase/supabase-js@2.49.4';

// ---------- shared: razorpay-core.ts ----------
/**
 * Razorpay core: the pure logic behind Gathbandhan's optional Razorpay payments.
 *
 * Shared by the Supabase Edge Functions (Deno) and the Angular app and its Karma tests, so it
 * uses only what both have: Web Crypto (`crypto.subtle`), TextEncoder and plain objects. No
 * network calls, no environment access and no secrets live here; callers pass them in.
 *
 * Amounts: shagun is whole rupees; Razorpay works in paise (1 rupee = 100 paise).
 */

const MIN_AMOUNT = 1;
/** Same cap as direct UPI, so a blessing never depends on the payment mode. */
const MAX_AMOUNT = 100_000;
const MESSAGE_MAX = 280;
const NAME_MIN = 2;
const NAME_MAX = 80;
/** Razorpay's standard domestic rate is about 2%, plus 18% GST on the fee: 2.36% in basis points. */
const DEFAULT_GATEWAY_FEE_BPS = 236;
const DEFAULT_PLATFORM_FEE_BPS = 0;

type FeeBearer = 'couple' | 'guest';
type GuestSide = 'bride' | 'groom';
type PaymentState = 'pending' | 'paid' | 'failed';
type PayoutStatus = 'not_set_up' | 'under_review' | 'active' | 'needs_info';

type Result<T> = { ok: true; value: T } | { ok: false; error: string };

const isObject = (v: unknown): v is Record<string, unknown> => !!v && typeof v === 'object' && !Array.isArray(v);
const str = (v: unknown) => (typeof v === 'string' ? v : '');

// ---------- order input ----------

interface OrderInput {
  slug: string;
  goalId: string;
  /** Whole rupees. */
  amount: number;
  guestName: string;
  message: string;
  side: GuestSide | null;
  /** 91XXXXXXXXXX, or null when the guest left it empty. */
  phone: string | null;
}

/** Indian mobile as 91 + 10 digits; null for empty; undefined when it is not a valid number. */
function normalizePhone(raw: unknown): string | null | undefined {
  const digits = str(raw).replace(/\D/g, '');
  if (!digits) return null;
  const ten = digits.length === 12 && digits.startsWith('91') ? digits.slice(2) : digits.length === 11 && digits.startsWith('0') ? digits.slice(1) : digits;
  return /^[6-9]\d{9}$/.test(ten) ? `91${ten}` : undefined;
}

/** Checks what the give page sends before anything touches the database or Razorpay. */
function validateOrderInput(raw: unknown): Result<OrderInput> {
  if (!isObject(raw)) return { ok: false, error: 'Missing payment details.' };
  const slug = str(raw['slug']).trim();
  if (!/^[a-z0-9][a-z0-9-]{0,59}$/.test(slug)) return { ok: false, error: 'Unknown wedding page.' };
  const goalId = str(raw['goalId']).trim();
  if (goalId.length < 1 || goalId.length > 40) return { ok: false, error: 'Choose a dream to bless.' };
  const amount = raw['amount'];
  if (typeof amount !== 'number' || !Number.isInteger(amount) || amount < MIN_AMOUNT || amount > MAX_AMOUNT) {
    return { ok: false, error: `Enter a whole amount between ₹${MIN_AMOUNT} and ₹${MAX_AMOUNT.toLocaleString('en-IN')}.` };
  }
  const guestName = str(raw['guestName']).trim().replace(/\s+/g, ' ');
  if (guestName.length < NAME_MIN || guestName.length > NAME_MAX) return { ok: false, error: 'Tell the couple who this blessing is from.' };
  if (raw['message'] !== undefined && typeof raw['message'] !== 'string') return { ok: false, error: 'The message is not text.' };
  const message = str(raw['message']).trim();
  if (message.length > MESSAGE_MAX) return { ok: false, error: `Keep the message under ${MESSAGE_MAX} characters.` };
  const sideRaw = raw['side'];
  if (sideRaw !== undefined && sideRaw !== null && sideRaw !== 'bride' && sideRaw !== 'groom') return { ok: false, error: 'Unknown side.' };
  const phone = normalizePhone(raw['phone']);
  if (phone === undefined) return { ok: false, error: 'Enter a 10-digit Indian mobile number, or leave it empty.' };
  return { ok: true, value: { slug, goalId, amount, guestName, message, side: (sideRaw as GuestSide | null | undefined) ?? null, phone } };
}

// ---------- fees ----------

interface FeeBreakdown {
  /** The shagun itself. */
  amountPaise: number;
  /** Added on top when the guest bears the fees (0 otherwise). */
  convenienceFeePaise: number;
  /** What Razorpay charges the guest. */
  totalPaise: number;
  /** Estimated gateway fee incl. GST, deducted by Razorpay from the platform account. */
  gatewayFeePaise: number;
  platformFeePaise: number;
  /** What the Route transfer sends to the couple's linked account. */
  payoutPaise: number;
}

const clampBps = (bps: number) => (Number.isFinite(bps) ? Math.min(2_000, Math.max(0, Math.round(bps))) : 0);

/**
 * Who pays the gateway fee. Couple: the guest pays the shagun and the couple receives it minus
 * fees. Guest: a convenience fee is added so the couple receives the full shagun.
 */
function feeBreakdown(amount: number, bearer: FeeBearer, gatewayBps = DEFAULT_GATEWAY_FEE_BPS, platformBps = DEFAULT_PLATFORM_FEE_BPS): FeeBreakdown {
  const gw = clampBps(gatewayBps);
  const pf = clampBps(platformBps);
  const amountPaise = Math.round(amount * 100);
  const platformFeePaise = Math.round((amountPaise * pf) / 10_000);
  if (bearer === 'guest') {
    // Charge T so that T minus the gateway fee on T still covers the whole shagun.
    const totalPaise = Math.ceil((amountPaise * 10_000) / (10_000 - gw));
    return {
      amountPaise,
      convenienceFeePaise: totalPaise - amountPaise,
      totalPaise,
      gatewayFeePaise: totalPaise - amountPaise,
      platformFeePaise,
      payoutPaise: Math.max(0, amountPaise - platformFeePaise),
    };
  }
  const gatewayFeePaise = Math.ceil((amountPaise * gw) / 10_000);
  return {
    amountPaise,
    convenienceFeePaise: 0,
    totalPaise: amountPaise,
    gatewayFeePaise,
    platformFeePaise,
    payoutPaise: Math.max(0, amountPaise - gatewayFeePaise - platformFeePaise),
  };
}

const paiseToRupees = (paise: number) => Math.round(paise) / 100;

// ---------- signatures ----------

function toHex(buf: ArrayBuffer): string {
  return [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, '0')).join('');
}

async function hmacSha256Hex(secret: string, message: string): Promise<string> {
  const enc = new TextEncoder();
  const key = await crypto.subtle.importKey('raw', enc.encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  return toHex(await crypto.subtle.sign('HMAC', key, enc.encode(message)));
}

/** Compares in time that depends only on the longer length, never on where the strings differ. */
function timingSafeEqual(a: string, b: string): boolean {
  const len = Math.max(a.length, b.length);
  let diff = a.length ^ b.length;
  for (let i = 0; i < len; i++) diff |= (a.charCodeAt(i) || 0) ^ (b.charCodeAt(i) || 0);
  return diff === 0;
}

interface CheckoutResponse {
  razorpay_order_id: string;
  razorpay_payment_id: string;
  razorpay_signature: string;
}

function isCheckoutResponse(v: unknown): v is CheckoutResponse {
  return isObject(v)
    && /^order_[A-Za-z0-9]{6,40}$/.test(str(v['razorpay_order_id']))
    && /^pay_[A-Za-z0-9]{6,40}$/.test(str(v['razorpay_payment_id']))
    && /^[a-f0-9]{64}$/i.test(str(v['razorpay_signature']));
}

/** Checkout's handler signature: HMAC_SHA256(order_id + "|" + payment_id, key_secret). */
async function verifyPaymentSignature(r: CheckoutResponse, keySecret: string): Promise<boolean> {
  if (!keySecret || !isCheckoutResponse(r)) return false;
  const expected = await hmacSha256Hex(keySecret, `${r.razorpay_order_id}|${r.razorpay_payment_id}`);
  return timingSafeEqual(expected, r.razorpay_signature.toLowerCase());
}

/** Webhooks: X-Razorpay-Signature = HMAC_SHA256(raw request body, webhook secret). */
async function verifyWebhookSignature(rawBody: string, signature: string | null | undefined, webhookSecret: string): Promise<boolean> {
  if (!webhookSecret || !signature || !/^[a-f0-9]{64}$/i.test(signature)) return false;
  const expected = await hmacSha256Hex(webhookSecret, rawBody);
  return timingSafeEqual(expected, signature.toLowerCase());
}

// ---------- webhooks ----------

type WebhookAction =
  | { kind: 'paid'; orderId: string; paymentId: string; amountPaise: number }
  | { kind: 'failed'; orderId: string; paymentId: string; reason: string }
  | { kind: 'transfer'; transferId: string; source: string; accountId: string; status: string }
  | { kind: 'account'; accountId: string; status: PayoutStatus; detail: string }
  | { kind: 'ignore'; event: string };

const entity = (payload: unknown, name: string): Record<string, unknown> => {
  const p = isObject(payload) ? payload[name] : undefined;
  const e = isObject(p) ? p['entity'] : undefined;
  return isObject(e) ? e : {};
};

/** Route linked-account / product activation status to the four states the couple sees. */
function mapAccountStatus(activationStatus: unknown): PayoutStatus {
  switch (str(activationStatus)) {
    case 'activated':
    case 'instantly_activated':
      return 'active';
    case 'needs_clarification':
    case 'rejected':
    case 'suspended':
      return 'needs_info';
    case '':
      return 'not_set_up';
    default:
      return 'under_review';
  }
}

/** What a webhook means for us. Unknown or malformed events are ignored (and still answered 200). */
function interpretWebhook(body: unknown): WebhookAction {
  if (!isObject(body)) return { kind: 'ignore', event: '' };
  const event = str(body['event']);
  const payload = body['payload'];
  if (event === 'payment.captured' || event === 'order.paid') {
    const pay = entity(payload, 'payment');
    const order = entity(payload, 'order');
    const orderId = str(pay['order_id']) || str(order['id']);
    const paymentId = str(pay['id']);
    const amountPaise = Number(pay['amount'] ?? order['amount_paid'] ?? 0);
    if (orderId && paymentId) return { kind: 'paid', orderId, paymentId, amountPaise };
  }
  if (event === 'payment.failed') {
    const pay = entity(payload, 'payment');
    const orderId = str(pay['order_id']);
    if (orderId) {
      return { kind: 'failed', orderId, paymentId: str(pay['id']), reason: (str(pay['error_description']) || 'Payment failed').slice(0, 200) };
    }
  }
  if (event.startsWith('transfer.')) {
    const t = entity(payload, 'transfer');
    if (str(t['id'])) return { kind: 'transfer', transferId: str(t['id']), source: str(t['source']), accountId: str(t['recipient']), status: event.slice('transfer.'.length) };
  }
  if (event.startsWith('account.') || event.startsWith('product.route.')) {
    const acc = entity(payload, 'account');
    const accountId = str(acc['id']) || str(body['account_id']);
    const status = event.startsWith('product.route.') ? event.slice('product.route.'.length) : event.slice('account.'.length);
    if (accountId) return { kind: 'account', accountId, status: mapAccountStatus(status), detail: '' };
  }
  return { kind: 'ignore', event };
}

// ---------- Razorpay order ----------

interface OrderContext {
  input: OrderInput;
  weddingId: string;
  couple: string;
  fees: FeeBreakdown;
  /** The couple's Route linked account; null sends no transfer (test mode only). */
  linkedAccountId: string | null;
  receipt: string;
}

const note = (s: string) => s.slice(0, 250);

/** Body for POST /v1/orders, with a Route transfer of the couple's share. */
function orderRequest(c: OrderContext): Record<string, unknown> {
  const body: Record<string, unknown> = {
    amount: c.fees.totalPaise,
    currency: 'INR',
    receipt: c.receipt.slice(0, 40),
    notes: {
      purpose: 'shagun',
      wedding_id: note(c.weddingId),
      goal_id: note(c.input.goalId),
      guest_name: note(c.input.guestName),
      couple: note(c.couple),
    },
  };
  if (c.linkedAccountId && c.fees.payoutPaise > 0) {
    body['transfers'] = [
      {
        account: c.linkedAccountId,
        amount: c.fees.payoutPaise,
        currency: 'INR',
        notes: { purpose: 'shagun', guest_name: note(c.input.guestName) },
        linked_account_notes: ['purpose', 'guest_name'],
        on_hold: false,
      },
    ];
  }
  return body;
}

// ---------- payout onboarding (Route linked account) ----------

interface PayoutForm {
  legalName: string;
  email: string;
  /** 10 digits. */
  phone: string;
  pan: string;
  accountNumber: string;
  ifsc: string;
  beneficiaryName: string;
  street: string;
  city: string;
  state: string;
  postalCode: string;
}

const PAYOUT_FIELDS: (keyof PayoutForm)[] = ['legalName', 'email', 'phone', 'pan', 'accountNumber', 'ifsc', 'beneficiaryName', 'street', 'city', 'state', 'postalCode'];

/** Field-by-field problems a couple can fix; empty when the form is fine. */
function payoutFormErrors(f: Partial<Record<keyof PayoutForm, unknown>>): Partial<Record<keyof PayoutForm, string>> {
  const e: Partial<Record<keyof PayoutForm, string>> = {};
  const v = (k: keyof PayoutForm) => str(f[k]).trim();
  if (v('legalName').length < 3 || v('legalName').length > 120) e.legalName = 'Your full name as on PAN.';
  if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(v('email')) || v('email').length > 254) e.email = 'A valid email address.';
  if (!/^[6-9]\d{9}$/.test(v('phone').replace(/\D/g, '').replace(/^91(?=\d{10}$)/, ''))) e.phone = 'A 10-digit Indian mobile number.';
  if (!/^[A-Z]{5}[0-9]{4}[A-Z]$/.test(v('pan').toUpperCase())) e.pan = 'PAN looks like ABCDE1234F.';
  if (!/^\d{9,18}$/.test(v('accountNumber').replace(/\s/g, ''))) e.accountNumber = 'Bank account number: 9 to 18 digits.';
  if (!/^[A-Z]{4}0[A-Z0-9]{6}$/.test(v('ifsc').toUpperCase())) e.ifsc = 'IFSC looks like HDFC0001234.';
  if (v('beneficiaryName').length < 3 || v('beneficiaryName').length > 120) e.beneficiaryName = 'Name on the bank account.';
  if (v('street').length < 3 || v('street').length > 100) e.street = 'House and street.';
  if (v('city').length < 2 || v('city').length > 60) e.city = 'City.';
  if (v('state').length < 2 || v('state').length > 60) e.state = 'State.';
  if (!/^[1-9]\d{5}$/.test(v('postalCode'))) e.postalCode = '6-digit PIN code.';
  return e;
}

function validatePayoutForm(raw: unknown): Result<PayoutForm> {
  if (!isObject(raw)) return { ok: false, error: 'Missing payout details.' };
  const errors = payoutFormErrors(raw as Partial<Record<keyof PayoutForm, unknown>>);
  const first = PAYOUT_FIELDS.find((k) => errors[k]);
  if (first) return { ok: false, error: errors[first]! };
  const v = (k: keyof PayoutForm) => str(raw[k]).trim();
  return {
    ok: true,
    value: {
      legalName: v('legalName'),
      email: v('email').toLowerCase(),
      phone: v('phone').replace(/\D/g, '').slice(-10),
      pan: v('pan').toUpperCase(),
      accountNumber: v('accountNumber').replace(/\s/g, ''),
      ifsc: v('ifsc').toUpperCase(),
      beneficiaryName: v('beneficiaryName'),
      street: v('street'),
      city: v('city'),
      state: v('state').toUpperCase(),
      postalCode: v('postalCode'),
    },
  };
}

/** Last n characters, the only part of a bank account or PAN that is ever stored. */
function lastChars(value: string, n = 4): string {
  return value.replace(/\s/g, '').slice(-n);
}

interface LinkedAccountRequests {
  account: Record<string, unknown>;
  stakeholder: Record<string, unknown>;
  product: Record<string, unknown>;
  productConfig: Record<string, unknown>;
}

/** Bodies for Route onboarding: /v2/accounts, its stakeholder, the route product and its settlement config. */
function linkedAccountRequests(f: PayoutForm, referenceId: string, category = 'others', subcategory = 'others'): LinkedAccountRequests {
  return {
    account: {
      email: f.email,
      phone: f.phone,
      type: 'route',
      reference_id: referenceId.slice(0, 20),
      legal_business_name: f.legalName,
      business_type: 'individual',
      contact_name: f.legalName,
      profile: {
        category,
        subcategory,
        addresses: { registered: { street1: f.street, street2: f.city, city: f.city, state: f.state, postal_code: f.postalCode, country: 'IN' } },
      },
    },
    stakeholder: { name: f.legalName, email: f.email, kyc: { pan: f.pan } },
    product: { product_name: 'route', tnc_accepted: true },
    productConfig: {
      settlements: { account_number: f.accountNumber, ifsc_code: f.ifsc, beneficiary_name: f.beneficiaryName },
      tnc_accepted: true,
    },
  };
}

/** Requirements Razorpay lists on a product config, as one short line for the couple. */
function requirementsText(product: unknown): string {
  const reqs = isObject(product) && Array.isArray(product['requirements']) ? product['requirements'] : [];
  return reqs
    .map((r) => (isObject(r) ? str(r['field_reference']) || str(r['reason_code']) : ''))
    .filter(Boolean)
    .join(', ')
    .slice(0, 480);
}

// ---------- keys and CORS ----------

const isTestKey = (keyId: string | null | undefined) => /^rzp_test_[A-Za-z0-9]+$/.test(keyId ?? '');
const isKeyId = (keyId: string | null | undefined) => /^rzp_(test|live)_[A-Za-z0-9]+$/.test(keyId ?? '');

const PAGES_ORIGIN = 'https://konicamaheshwarii.github.io';

/** The published site and local development (http://localhost on any port) only. */
function isAllowedOrigin(origin: string | null | undefined): boolean {
  return origin === PAGES_ORIGIN || /^http:\/\/localhost(:\d{1,5})?$/.test(origin ?? '');
}

function corsHeaders(origin: string | null | undefined): Record<string, string> {
  const headers: Record<string, string> = {
    'Access-Control-Allow-Methods': 'POST, OPTIONS',
    'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
    'Access-Control-Max-Age': '86400',
    Vary: 'Origin',
  };
  if (isAllowedOrigin(origin)) headers['Access-Control-Allow-Origin'] = origin!;
  return headers;
}

// ---------- shared: edge.ts ----------
// Deno-only helpers for the Razorpay Edge Functions: environment, JSON responses, the
// service-role database client and the Razorpay REST client. Secrets are read from the
// environment (Supabase → Edge Functions → Secrets) and are never logged or returned.

function env(name: string, fallback?: string): string {
  const value = Deno.env.get(name) ?? fallback;
  if (value === undefined || value === '') throw new ConfigError(`${name} is not set`);
  return value;
}

/** A missing secret: the owner has not finished setup. Reported without the value. */
class ConfigError extends Error {}

/** An error with a message that is safe to show the guest or couple. */
class HttpError extends Error {
  constructor(readonly status: number, message: string) {
    super(message);
  }
}

function json(body: unknown, status: number, origin: string | null): Response {
  return new Response(JSON.stringify(body), { status, headers: { ...corsHeaders(origin), 'Content-Type': 'application/json' } });
}

function preflight(origin: string | null): Response {
  return new Response(null, { status: 204, headers: corsHeaders(origin) });
}

/** Runs a handler with CORS, method checks and safe error reporting. */
function serve(handler: (req: Request, origin: string | null) => Promise<Response>, opts: { cors: boolean } = { cors: true }): void {
  Deno.serve(async (req) => {
    const origin = req.headers.get('origin');
    if (opts.cors && req.method === 'OPTIONS') return preflight(origin);
    if (req.method !== 'POST') return json({ error: 'Method not allowed' }, 405, origin);
    try {
      return await handler(req, origin);
    } catch (e) {
      if (e instanceof HttpError) return json({ error: e.message }, e.status, origin);
      if (e instanceof ConfigError) {
        console.error('Configuration problem:', e.message);
        return json({ error: 'Payments are not fully set up yet. Please pay by UPI for now.' }, 503, origin);
      }
      console.error('Unexpected error:', e instanceof Error ? e.message : 'unknown');
      return json({ error: 'Something went wrong. Please try again.' }, 500, origin);
    }
  });
}

/** Service-role client: bypasses RLS, so only these functions can set a payment "paid". */
function admin(): SupabaseClient {
  return createClient(env('SUPABASE_URL'), env('SUPABASE_SERVICE_ROLE_KEY'), { auth: { persistSession: false, autoRefreshToken: false } });
}

interface RazorpayError {
  status: number;
  description: string;
}

/** Calls the Razorpay REST API with Basic auth (key id + secret). Throws RazorpayError. */
async function razorpay<T = Record<string, unknown>>(method: 'GET' | 'POST' | 'PATCH', path: string, body?: unknown): Promise<T> {
  const auth = btoa(`${env('RAZORPAY_KEY_ID')}:${env('RAZORPAY_KEY_SECRET')}`);
  const res = await fetch(`https://api.razorpay.com${path}`, {
    method,
    headers: { Authorization: `Basic ${auth}`, 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok) {
    const description = (data as { error?: { description?: string } }).error?.description ?? `Razorpay returned ${res.status}`;
    throw { status: res.status, description } satisfies RazorpayError;
  }
  return data as T;
}

const isRazorpayError = (e: unknown): e is RazorpayError =>
  !!e && typeof e === 'object' && 'description' in e && 'status' in e;

// ---------- razorpay-create-order/index.ts ----------
// razorpay-create-order: a guest starts a Razorpay payment for a shagun.
// Validates against the database, creates a Razorpay order whose Route transfer sends the
// couple's share to their linked account, records a "pending" contribution, and returns what
// Razorpay Checkout needs. Deploy with JWT verification off (guests are not signed in).

serve(async (req, origin) => {
  if (!isAllowedOrigin(origin)) throw new HttpError(403, 'Origin not allowed');
  const parsed = validateOrderInput(await req.json().catch(() => null));
  if (!parsed.ok) throw new HttpError(400, parsed.error);
  const input = parsed.value;

  const keyId = env('RAZORPAY_KEY_ID');
  env('RAZORPAY_KEY_SECRET'); // fail early (503) when the secret is missing
  const testMode = isTestKey(keyId);
  const db = admin();

  const { data: w } = await db
    .from('shagun_weddings')
    .select('id, partner1, partner2, payment_mode, fee_bearer, details')
    .eq('slug', input.slug)
    .maybeSingle();
  if (!w) throw new HttpError(404, 'We could not find this wedding page.');
  if (w.payment_mode !== 'razorpay') throw new HttpError(409, 'This couple takes shagun by UPI directly.');
  const goals: { id?: string }[] = Array.isArray(w.details?.goals) ? w.details.goals : [];
  if (!goals.some((g) => g.id === input.goalId)) throw new HttpError(400, 'This dream is not on the wedding page.');

  const { data: account } = await db
    .from('shagun_payout_accounts')
    .select('razorpay_account_id, status, route_enabled')
    .eq('wedding_id', w.id)
    .maybeSingle();
  const routed = account?.status === 'active' && account.route_enabled && account.razorpay_account_id ? account.razorpay_account_id as string : null;
  // Live payments must settle to the couple. Test mode may run without Route (no real money).
  if (!routed && !testMode) throw new HttpError(409, "The couple's payout account is not active yet. Please pay by UPI for now.");

  const fees = feeBreakdown(
    input.amount,
    (w.fee_bearer === 'guest' ? 'guest' : 'couple') as FeeBearer,
    Number(Deno.env.get('GATEWAY_FEE_BPS') ?? 236),
    Number(Deno.env.get('PLATFORM_FEE_BPS') ?? 0),
  );
  const receipt = `sg_${crypto.randomUUID().replace(/-/g, '').slice(0, 30)}`;

  let order: { id: string };
  try {
    order = await razorpay<{ id: string }>('POST', '/v1/orders', orderRequest({
      input,
      weddingId: w.id,
      couple: `${w.partner1} & ${w.partner2}`,
      fees,
      linkedAccountId: routed,
      receipt,
    }));
  } catch (e) {
    if (isRazorpayError(e)) {
      console.error('Razorpay order failed:', e.status, e.description);
      throw new HttpError(502, 'Razorpay could not start this payment. Please try again, or pay by UPI.');
    }
    throw e;
  }

  const contributionId = crypto.randomUUID();
  const { error } = await db.from('shagun_contributions').insert({
    id: contributionId,
    wedding_id: w.id,
    goal_id: input.goalId,
    guest_name: input.guestName,
    amount: input.amount,
    message: input.message,
    phone: input.phone,
    side: input.side,
    provider: 'razorpay',
    status: 'pending',
    razorpay_order_id: order.id,
    charged_amount: paiseToRupees(fees.totalPaise),
    guest_fee: paiseToRupees(fees.convenienceFeePaise),
    fee_amount: paiseToRupees(fees.gatewayFeePaise + fees.platformFeePaise),
  });
  if (error) {
    console.error('Could not record the pending contribution:', error.code);
    throw new HttpError(500, 'Could not start the payment. Please try again.');
  }

  return json({
    orderId: order.id,
    keyId,
    currency: 'INR',
    amount: input.amount,
    amountPaise: fees.totalPaise,
    convenienceFee: paiseToRupees(fees.convenienceFeePaise),
    total: paiseToRupees(fees.totalPaise),
    contributionId,
    testMode,
    routed: !!routed,
  }, 200, origin);
});
